import{_ as t,a as r,o,a6 as a}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Place Order","description":"","frontmatter":{"outline":false,"examples":[{"id":"place-order-onsite","title":"Place Order (on-site payment)","description":"Cash-on-delivery or money-transfer — the order is created immediately. Address, shipping method, and payment method must already be set on the cart, so the body is empty.","request":"POST /api/shop/checkout-orders\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n\\n{}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 9372,\\n  \\"cartToken\\": \\"1536\\",\\n  \\"orderId\\": \\"554\\",\\n  \\"redirect\\": false,\\n  \\"redirectUrl\\": null,\\n  \\"success\\": true,\\n  \\"message\\": \\"Order placed successfully\\"\\n}\\n"},{"id":"place-order-redirect","title":"Place Order (payment gateway)","description":"Stripe / PayU / PhonePe / Razorpay / PayPal — no order is created yet; redirect the shopper to redirectUrl to complete payment.","request":"POST /api/shop/checkout-orders\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n\\n{}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 9372,\\n  \\"cartToken\\": \\"1536\\",\\n  \\"orderId\\": null,\\n  \\"redirect\\": true,\\n  \\"redirectUrl\\": \\"https://your-domain.com/stripe/redirect\\",\\n  \\"success\\": true,\\n  \\"message\\": \\"This payment method requires the shopper to complete payment on the gateway. Send them to redirectUrl; the order is created once the gateway confirms the payment.\\"\\n}\\n","commonErrors":[{"error":"500 Internal Server Error — Cart is empty","cause":"The cart has no items, or a previous place-order already emptied it","solution":"Add items before placing; a repeated call after success fails this way"},{"error":"500 Internal Server Error — Billing address is required","cause":"The checkout address step has not been completed for this cart","solution":"Save the address with Set Checkout Address, then set shipping and payment"},{"error":"500 Internal Server Error — Shipping method is required","cause":"The cart holds shippable items but no shipping method is saved","solution":"Pick a rate from Get Shipping Methods and save it"},{"error":"500 Internal Server Error — Payment method is required","cause":"No payment method is saved on the cart","solution":"Save one with Set Payment Method"},{"error":"401 Unauthorized — Authentication token is required","cause":"No cart or customer token was sent as the Bearer token","solution":"Send the cartToken from Create Cart, or a logged-in customer's token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/checkout/place-order.md","filePath":"api/rest-api/shop/checkout/place-order.md","lastUpdated":1786429091000}`),s={name:"api/rest-api/shop/checkout/place-order.md"};function d(i,e,n,c,h,l){return o(),r("div",null,e[0]||(e[0]=[a('<h1 id="place-order" tabindex="-1">Place Order <a class="header-anchor" href="#place-order" aria-label="Permalink to &quot;Place Order&quot;">​</a></h1><p>Create an order from the shopping cart. This completes the checkout process.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/checkout-orders</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>The address, shipping method, and payment method are set on the cart in the preceding checkout steps, so place-order takes an <strong>empty body</strong>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{}</span></span></code></pre></div><h2 id="response-fields-201-created" tabindex="-1">Response Fields (201 Created) <a class="header-anchor" href="#response-fields-201-created" aria-label="Permalink to &quot;Response Fields (201 Created)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>The cart id the order was placed from (not the order id).</td></tr><tr><td><code>cartToken</code></td><td>string</td><td>The cart token.</td></tr><tr><td><code>orderId</code></td><td>string</td><td>The created order id — <strong>only set on the on-site path</strong>; <code>null</code> when a payment redirect is required.</td></tr><tr><td><code>redirect</code></td><td>boolean</td><td><code>true</code> when the payment method needs the shopper sent to a payment page before the order exists.</td></tr><tr><td><code>redirectUrl</code></td><td>string</td><td>The payment page to open when <code>redirect</code> is <code>true</code>; <code>null</code> otherwise.</td></tr><tr><td><code>success</code></td><td>boolean</td><td><code>true</code> when the call succeeded — order placed <strong>or</strong> redirect required. Failures return a 4xx with the reason, not <code>success: false</code>.</td></tr><tr><td><code>message</code></td><td>string</td><td>Human-readable result — &quot;order placed&quot;, or an explanation to redirect the shopper to complete payment.</td></tr></tbody></table><h3 id="two-outcomes-—-branch-on-redirect" tabindex="-1">Two outcomes — branch on <code>redirect</code> <a class="header-anchor" href="#two-outcomes-—-branch-on-redirect" aria-label="Permalink to &quot;Two outcomes — branch on `redirect`&quot;">​</a></h3><ul><li><strong><code>redirect: false</code></strong> (cash-on-delivery, money-transfer) — the order exists; read <code>orderId</code>.</li><li><strong><code>redirect: true</code></strong> (stripe, payu, phonepe, razorpay, paypal) — <strong>no order yet</strong>. <code>orderId</code> is <code>null</code>; send the shopper to <code>redirectUrl</code> to pay. The order is created when the gateway returns to your success URL. <code>message</code> explains this.</li></ul><p>On a genuine failure (empty cart, missing address/shipping/payment, suspended account, minimum-order not met) the endpoint returns a <strong>4xx</strong> with the exact reason in the error body — it does not return <code>success: false</code>.</p><h2 id="order-status-values" tabindex="-1">Order Status Values <a class="header-anchor" href="#order-status-values" aria-label="Permalink to &quot;Order Status Values&quot;">​</a></h2><p>A newly placed order starts at <code>pending</code>, or <code>processing</code> once payment is confirmed. The full set a storefront can see is listed on <a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Each step writes to the cart, and place-order reads what they left behind. They must run in this order:</p><ol><li>A cart with at least one item — otherwise <code>Cart is empty</code>.</li><li>A billing address, and a shipping address when the cart holds shippable items — otherwise <code>Billing address is required</code>.</li><li>A shipping method, for a cart with shippable items.</li><li>A payment method.</li></ol><p>Every failure is reported as a <code>500</code> with the reason in <code>detail</code>, not as a <code>4xx</code> and not as <code>success: false</code>. Read <code>detail</code> to know which step is missing.</p><h2 id="after-the-order-is-placed" tabindex="-1">After the Order Is Placed <a class="header-anchor" href="#after-the-order-is-placed" aria-label="Permalink to &quot;After the Order Is Placed&quot;">​</a></h2><ul><li>The cart is emptied and its token can no longer be used for checkout.</li><li>The order confirmation email goes out to the address captured at checkout.</li><li>The order appears in <a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> for a logged-in shopper. A guest order is not listed there — keep the returned <code>orderId</code> client-side.</li><li>The invoice is created by the store, not at checkout, so <a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">Get Customer Invoices</a> may be empty right after placing.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Finish a guest checkout</strong> — the whole flow works with the cart token alone; capture <code>orderId</code> from the response, since a guest cannot look the order up afterwards.</li><li><strong>Gateway checkout</strong> — when <code>redirect</code> is <code>true</code>, hand the shopper to <code>redirectUrl</code> and wait for the gateway to return; do not treat the missing <code>orderId</code> as a failure.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Branch on <code>redirect</code> before reading <code>orderId</code></strong> — on the redirect path there is no order yet and <code>orderId</code> is <code>null</code>.</li><li><strong>Read <code>detail</code> on a failure, not the status code</strong> — every missing prerequisite is a <code>500</code>, so only the message identifies which step to send the shopper back to.</li><li><strong>Store <code>orderId</code> for guests immediately</strong> — there is no guest order-lookup endpoint.</li><li><strong>Do not retry blindly after a success</strong> — the cart is emptied, so a second call fails with <code>Cart is empty</code> rather than duplicating the order.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> — read the current items and recalculated totals</li><li><a href="/api/rest-api/shop/checkout/set-shipping-address.html">Set Shipping Address</a> — the same call with a separate delivery address</li><li><a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Billing Address</a> — save both checkout addresses in one call</li><li><a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a> — save the chosen rate on the cart</li><li><a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a> — save the chosen payment method on the cart</li><li><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> — the customer&#39;s order history</li></ul>',28)]))}const m=t(s,[["render",d]]);export{u as __pageData,m as default};
